"""Billing for invoices. Rate lookups are billed, so the charge is remembered."""
import rates


class InvoiceBill:
    def __init__(self):
        self._invoices = []
        self._charge = None

    def add(self, invoice):
        """Add one invoice to the bill."""
        self._invoices.append(invoice)

    def charge(self):
        """Return the total charge: due times the rate for each invoice's client.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.due * rates.rate_for(x.client) for x in self._invoices)
        return self._charge


def group_by_client(invoices):
    """Return a dict from client to the list of invoices with that client."""
    groups = {}
    for x in invoices:
        groups.setdefault(x.client, []).append(x)
    return groups


def client_names(invoices):
    """Return the distinct client values, in first-seen order."""
    names = []
    for x in invoices:
        if x.client not in names:
            names.append(x.client)
    return names

